# ============================================================================
# Утилиты
# ============================================================================

def log(msg: str) -> None:
    print(f"  {msg}")


def ok(msg: str) -> None:
    print(f"  ✓ {msg}")


def warn(msg: str) -> None:
    print(f"  ⚠️  {msg}")


def err(msg: str) -> None:
    print(f"  ❌ {msg}", file=sys.stderr)


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def write_text(path: Path, text: str) -> None:
    path.write_text(text, encoding="utf-8")


def patch_file(path: Path, old: str, new: str, *, count: int = 1) -> bool:
    """Заменяет `old` на `new` в файле. Требует ровно `count` совпадений."""
    if not path.exists():
        err(f"Файл не найден: {path}")
        return False
    text = read_text(path)
    found = text.count(old)
    if found != count:
        err(f"Ожидалось {count} совпадений, найдено {found} в {path}")
        err(f"OLD блок (первые 200 символов): {old[:200]!r}")
        return False
    new_text = text.replace(old, new, count)
    write_text(path, new_text)
    return True


