def stage_9() -> None:
    print("\n=== Этап 9: features/export/ui.py — build_kb + интеграция ===")
    ui_path = REPO_ROOT / "features" / "export" / "ui.py"
    if not ui_path.exists():
        err(f"Не найден {ui_path}")
        return

    text = read_text(ui_path)

    # Проверяем, что патч ещё не применён
    if "build_kb" in text and "KnowledgeBaseBuilder" in text:
        ok(f"{ui_path.name} — build_kb уже интегрирован")
        return

    # Применяем обе замены
    if not patch_file(ui_path, UI_OLD_PARAMS, UI_NEW_PARAMS):
        err("Не удалось применить патч к ExportParams")
        err("Возможно, файл был изменён — проверь сигнатуру ExportParams")
        return
    ok(f"{ui_path.name} — поле build_kb добавлено в ExportParams")

    # Перечитываем файл, т.к. он изменился
    if not patch_file(ui_path, UI_OLD_RUN, UI_NEW_RUN):
        err("Не удалось применить патч к ExportWorker.run()")
        err("Скорее всего, изменился отступ или пробелы в конце HTML-блока")
        err("Проверь строки после `all_files.extend(html_paths)` в ExportWorker.run()")
        return
    ok(f"{ui_path.name} — блок build_kb добавлен в ExportWorker.run()")


# ============================================================================
# Этапы 2-8: features/export/knowledge_base.py (новый файл)
# ============================================================================

# Base64-содержимое knowledge_base.py — инлайн, чтобы один файл-патч.
# Сгенерировано из проверенного модуля в репозитории разработчика.
KB_MODULE_B64 = ""


def stage_2_to_8() -> None:
    print("\n=== Этапы 2-8: features/export/knowledge_base.py ===")
    kb_path = REPO_ROOT / "features" / "export" / "knowledge_base.py"
    kb_path.parent.mkdir(parents=True, exist_ok=True)

    if kb_path.exists():
        existing = read_text(kb_path)
        if "KnowledgeBaseBuilder" in existing and "enrich_md_files" in existing:
            ok(f"{kb_path.name} уже существует и содержит KnowledgeBaseBuilder")
            return
        log(f"{kb_path.name} существует, но без enrich_md_files — перезаписываю…")

    if KB_MODULE_B64.startswith("<!--"):
        err("Base64-блок не подставлен! Положи содержимое kb_module.b64")
        err("в константу KB_MODULE_B64 (одной строкой).")
        return

    try:
        module_text = base64.b64decode(KB_MODULE_B64).decode("utf-8")
    except Exception as exc:
        err(f"Не удалось декодировать base64: {exc}")
        return

    write_text(kb_path, module_text)
    ok(f"{kb_path.name} создан ({len(module_text.splitlines())} строк)")


